// cannot infer is configured here.
const config: KnipConfig = {
  workspaces: {
    ".": {
      // The root only orchestrates; its tools are used by name in scripts.
      entry: [],
    },
    app: {
      project: ["src/**/*.{ts,tsx,css}", "test/**/*.{ts,tsx}"],
      ignore: [
        // Generated by openapi-typescript: exports every schema/operation by
        // design, whether or not the app uses it yet.
        "src/lib/api/schema.gen.ts",
        // Deliberately boundary-violating sources cruised by the architecture test.
        "test/fixtures/**",
      ],
    },
  },
};

export default config;
